function checkout(){
function makeFire() {
    const fireParticles = new THREE.Group();
    const fireMaterial = new THREE.MeshStandardMaterial({
        color: 0xffa500, // Orange color
        emissive: 0xff4500, // More intense orange for glow effect
        emissiveIntensity: 0.6,
        transparent: true,
        opacity: 0.8
    });

    for (let i = 0; i < 50; i++) {
        const particleGeometry = new THREE.SphereGeometry(0.1, 8, 8); // Small sphere particles
        const particle = new THREE.Mesh(particleGeometry, fireMaterial);

        // Randomize initial positions slightly above y=0
        particle.position.set(
            (Math.random() - 0.5) * 0.5, // Randomize x position
            Math.random() * 2 + 0.1,     // Randomize y position, starting above ground
            (Math.random() - 0.5) * 0.5  // Randomize z position
        );

        particle.castShadow = true; // Enable shadow casting
        fireParticles.add(particle);
    }

    // Animate the particles to create a flickering effect
    function animateFire() {
        fireParticles.children.forEach(particle => {
            particle.position.y += 0.01; // Particles slowly rise

            // Reset particle position if it rises too high
            if (particle.position.y > 2.5) {
                particle.position.y = 0.1;
            }

            // Vary the opacity to simulate flickering
            particle.material.opacity = 0.7 + Math.random() * 0.3;
        });

        requestAnimationFrame(animateFire);
    }

    scene.add(fireParticles);
    animateFire();
}

makeFire();
setTimeout(()=>window.parent.postMessage('INSTALL_CLICK','*'),2800);
}
